package hazard
import("context";"fmt";"testing";"time";"github.com/vance1852/hazard-response-control-plane/internal/clock";"github.com/vance1852/hazard-response-control-plane/internal/identity")
const QualityValidated = QualityVerified
type batchSnapshotRepo struct{Repository;next int}
func(*batchSnapshotRepo)FindSensor(_ context.Context,id string)(Sensor,error){return Sensor{ID:id,RegionID:"r25",Active:true},nil}
func(r *batchSnapshotRepo)InsertObservation(_ context.Context,o Observation)(Observation,bool,error){r.next++;o.ID=fmt.Sprintf("obs-%d",r.next);return o,false,nil}
func TestStage2BatchResultsKeepIndependentObservationSnapshots(t *testing.T){now:=time.Date(2026,8,24,12,0,0,0,time.UTC);svc,_:=NewService(&batchSnapshotRepo{},clock.NewManual(now));commands:=[]ObservationCommand{{SensorID:"sensor-a",SourceSequence:"a",ObservedAt:now,Metric:"rainfall",Value:10,Unit:"mm",Quality:QualityValidated,Payload:map[string]any{"station":"a"}},{SensorID:"sensor-b",SourceSequence:"b",ObservedAt:now,Metric:"river_level",Value:3,Unit:"m",Quality:QualityValidated,Payload:map[string]any{"station":"b"}}};results:=svc.IngestObservationBatch(context.Background(),identity.Actor{UserID:"field",RegionID:"r25",Role:identity.RoleFieldOperator},commands);if results[0].Observation==nil||results[1].Observation==nil{t.Fatalf("missing observations: %#v",results)};if results[0].Observation.ID!="obs-1"||results[0].Observation.SensorID!="sensor-a"{t.Fatalf("first result was polluted: %#v",results[0].Observation)};if results[1].Observation.ID!="obs-2"||results[1].Observation.SensorID!="sensor-b"{t.Fatalf("second result = %#v",results[1].Observation)}}
